const proxyProviderOutcomes = `-- name: ProxyProviderOutcomes :many
SELECT
    p.provider,
    coalesce(sum(o.count), 0)::bigint AS requests,
    coalesce(sum(o.count) FILTER (WHERE o.outcome = 'success'), 0)::bigint AS successes,
    coalesce(sum(o.count) FILTER (WHERE o.outcome = ANY($1::text[])), 0)::bigint AS risks,
    coalesce(sum(o.latency_ms_sum), 0)::bigint AS latency_ms_sum
FROM outcome_stats_minutely AS o
JOIN proxies AS p ON p.id = o.proxy_id AND p.namespace_id = o.namespace_id
WHERE o.namespace_id = $2
  AND o.bucket >= $3::timestamptz
  AND o.bucket < $4::timestamptz
  AND o.proxy_id <> ''
  AND ($5::boolean OR o.site_id = ANY($6::text[]))
GROUP BY p.provider
`

type ProxyProviderOutcomesParams struct {
	RiskOutcomes []string  `json:"risk_outcomes"`
	NamespaceID  string    `json:"namespace_id"`
	RangeStart   time.Time `json:"range_start"`
	RangeEnd     time.Time `json:"range_end"`
	AllSites     bool      `json:"all_sites"`
	SiteIds      []string  `json:"site_ids"`
}

type ProxyProviderOutcomesRow struct {
	Provider     string `json:"provider"`
	Requests     int64  `json:"requests"`
	Successes    int64  `json:"successes"`
	Risks        int64  `json:"risks"`
	LatencyMsSum int64  `json:"latency_ms_sum"`
}

func (q *Queries) ProxyProviderOutcomes(ctx context.Context, arg ProxyProviderOutcomesParams) ([]ProxyProviderOutcomesRow, error) {
	rows, err := q.db.Query(ctx, proxyProviderOutcomes,
		arg.RiskOutcomes,
		arg.NamespaceID,
		arg.RangeStart,
		arg.RangeEnd,
		arg.AllSites,
		arg.SiteIds,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ProxyProviderOutcomesRow{}
	for rows.Next() {
		var i ProxyProviderOutcomesRow
		if err := rows.Scan(
			&i.Provider,
			&i.Requests,
			&i.Successes,
			&i.Risks,
			&i.LatencyMsSum,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

