const proxyUpdateAttributesBatch = `-- name: ProxyUpdateAttributesBatch :exec
UPDATE proxies AS p SET
    kind = u.kind,
    region = u.region,
    city = u.city,
    provider = u.provider,
    max_concurrency = u.max_concurrency,
    tags = CASE WHEN u.tags = '' THEN '{}'::text[] ELSE string_to_array(u.tags, ',') END,
    session_template = u.session_template,
    updated_at = now()
FROM (
    SELECT
        unnest($2::text[]) AS id,
        unnest($3::text[]) AS kind,
        unnest($4::text[]) AS region,
        unnest($5::text[]) AS city,
        unnest($6::text[]) AS provider,
        unnest($7::integer[]) AS max_concurrency,
        unnest($8::text[]) AS tags,
        unnest($9::text[]) AS session_template
) AS u
WHERE p.id = u.id AND p.namespace_id = $1::text
`

type ProxyUpdateAttributesBatchParams struct {
	NamespaceID      string   `json:"namespace_id"`
	Ids              []string `json:"ids"`
	Kinds            []string `json:"kinds"`
	Regions          []string `json:"regions"`
	Cities           []string `json:"cities"`
	Providers        []string `json:"providers"`
	MaxConcurrencies []int32  `json:"max_concurrencies"`
	Tags             []string `json:"tags"`
	SessionTemplates []string `json:"session_templates"`
}

func (q *Queries) ProxyUpdateAttributesBatch(ctx context.Context, arg ProxyUpdateAttributesBatchParams) error {
	_, err := q.db.Exec(ctx, proxyUpdateAttributesBatch,
		arg.NamespaceID,
		arg.Ids,
		arg.Kinds,
		arg.Regions,
		arg.Cities,
		arg.Providers,
		arg.MaxConcurrencies,
		arg.Tags,
		arg.SessionTemplates,
	)
	return err
}
